(async function () {
  const [
    { Editor, mergeAttributes, Node },
    { Placeholder },
    { default: StarterKit },
    { Link },
    { TextAlign },
    { Image },
    { TaskList },
    { TaskItem },
    { Color },
    { TextStyle },
    { Table },
    { TableRow },
    { TableCell },
    { TableHeader },
  ] = await Promise.all([
    import("https://esm.sh/@tiptap/core@2.2.4"),
    import("https://esm.sh/@tiptap/extension-placeholder@2.2.4"),
    import("https://esm.sh/@tiptap/starter-kit@2.2.4"),
    import("https://esm.sh/@tiptap/extension-link@2.2.4"),
    import("https://esm.sh/@tiptap/extension-text-align@2.2.4"),
    import("https://esm.sh/@tiptap/extension-image@2.2.4"),
    import("https://esm.sh/@tiptap/extension-task-list@2.2.4"),
    import("https://esm.sh/@tiptap/extension-task-item@2.2.4"),
    import("https://esm.sh/@tiptap/extension-color@2.2.4"),
    import("https://esm.sh/@tiptap/extension-text-style@2.2.4"),
    import("https://esm.sh/@tiptap/extension-table@2.2.4"),
    import("https://esm.sh/@tiptap/extension-table-row@2.2.4"),
    import("https://esm.sh/@tiptap/extension-table-cell@2.2.4"),
    import("https://esm.sh/@tiptap/extension-table-header@2.2.4"),
  ]).catch((err) => {
    console.log("Error loading Tiptap extensions:");
  });

  // ===================== File Upload Helpers =====================

  function fileToBase64(file) {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onloadend = () => {
        if (reader.result == null) {
          reject(new Error("FileReader result is null"));
        } else if (typeof reader.result === "string") {
          resolve(reader.result);
        }
      };
      reader.onerror = reject;
      reader.readAsDataURL(file);
    });
  }

  function getPostName() {
    if (window.cafePostName) return window.cafePostName;
    const pathMatch = window.location.pathname.match(/\/edit-post\/([^\/]+)/);
    if (pathMatch) return decodeURIComponent(pathMatch[1]);
    const urlParams = new URLSearchParams(window.location.search);
    return urlParams.get("name") || null;
  }

  async function uploadFile(file, options = {}) {
    return new Promise((resolve, reject) => {
      const xhr = new XMLHttpRequest();
      const formData = new FormData();

      formData.append("file", file, file.name);
      formData.append("is_private", options.private ? "1" : "0");
      formData.append("folder", options.folder || "Home");

      if (options.doctype) formData.append("doctype", options.doctype);
      if (options.docname) formData.append("docname", options.docname);
      if (options.fieldname)
        formData.append("fieldname", options.fieldname || "content");

      xhr.open(
        "POST",
        options.uploadEndpoint || "/api/method/upload_file",
        true,
      );
      xhr.setRequestHeader("Accept", "application/json");

      const csrfToken =
        window.csrf_token || (window.frappe && window.frappe.csrf_token);
      if (csrfToken && csrfToken !== "{{ csrf_token }}") {
        xhr.setRequestHeader("X-Frappe-CSRF-Token", csrfToken);
      }

      xhr.onreadystatechange = () => {
        if (xhr.readyState === XMLHttpRequest.DONE) {
          if (xhr.status === 200) {
            let r = null;
            try {
              r = JSON.parse(xhr.responseText);
            } catch (e) {
              r = xhr.responseText;
            }
            resolve(r.message || r);
          } else {
            let error = "Upload failed";
            try {
              const err = JSON.parse(xhr.responseText);
              error = err._error_message || err.message || error;
            } catch (e) {}
            reject(new Error(error));
          }
        }
      };

      xhr.onerror = () => reject(new Error("Network error during upload"));
      xhr.send(formData);
    });
  }

  const uploadMap = new Map();

  function uploadAndInsertImage(file, view, pos = null) {
    const uploadId = `upload-${Date.now()}-${Math.random()
      .toString(36)
      .substring(2, 9)}`;

    fileToBase64(file)
      .then((base64) => {
        uploadMap.set(uploadId, { file, base64 });

        const attrs = {
          src: base64,
          uploadId: uploadId,
          loading: true,
        };

        const node = view.state.schema.nodes.image.create(attrs);
        const tr = view.state.tr;

        if (pos != null) {
          tr.insert(pos, node);
        } else {
          tr.insert(tr.selection.from, node);
        }
        view.dispatch(tr);

        const postName = getPostName();
        return uploadFile(
          file,
          //
        );
      })
      .then((result) => {
        view.state.doc.descendants((node, nodePos) => {
          if (node.type.name === "image" && node.attrs.uploadId === uploadId) {
            const tr = view.state.tr.setNodeMarkup(nodePos, undefined, {
              ...node.attrs,
              src: result.file_url,
              loading: false,
            });
            view.dispatch(tr);
            uploadMap.delete(uploadId);
            return false;
          }
        });
      })
      .catch((error) => {
        view.state.doc.descendants((node, nodePos) => {
          if (node.type.name === "image" && node.attrs.uploadId === uploadId) {
            const tr = view.state.tr.setNodeMarkup(nodePos, undefined, {
              ...node.attrs,
              loading: false,
              error: error.message || "Failed to upload image",
            });
            view.dispatch(tr);
            return false;
          }
        });
      });
  }

  const CustomImage = Image.extend({
    addAttributes() {
      return {
        src: { default: null },
        alt: { default: null },
        title: { default: null },
        width: { default: null },
        height: { default: null },
        uploadId: { default: null },
        loading: { default: false },
        error: { default: null },
      };
    },
    renderHTML({ HTMLAttributes }) {
      const { uploadId, loading, error, ...rest } = HTMLAttributes;
      const dataAttrs = {};
      if (uploadId) dataAttrs["data-upload-id"] = uploadId;
      if (loading) dataAttrs["data-loading"] = "true";
      if (error) dataAttrs["data-error"] = error;
      return [
        "img",
        mergeAttributes(this.options.HTMLAttributes || {}, rest, dataAttrs),
      ];
    },
  });

  const CustomVideo = Node.create({
    name: "video",
    group: "block",
    selectable: true,
    draggable: true,
    atom: true,

    addAttributes() {
      return {
        src: { default: null },
        alt: { default: null },
        title: { default: null },
        width: { default: null },
        height: { default: null },
        autoplay: { default: false },
        loop: { default: false },
        muted: { default: false },
        uploadId: { default: null },
        loading: { default: false },
        error: { default: null },
      };
    },

    parseHTML() {
      return [
        {
          tag: "video",
          getAttrs: (node) => {
            if (typeof node === "string") return {};
            const element = node;
            return {
              src: element.getAttribute("src"),
              alt: element.getAttribute("alt"),
              title: element.getAttribute("title"),
              width: element.getAttribute("width"),
              height: element.getAttribute("height"),
              autoplay: element.hasAttribute("autoplay"),
              loop: element.hasAttribute("loop"),
              muted: element.hasAttribute("muted"),
            };
          },
        },
      ];
    },

    renderHTML({ HTMLAttributes }) {
      const { uploadId, loading, error, ...rest } = HTMLAttributes;
      const dataAttrs = {};
      if (uploadId) dataAttrs["data-upload-id"] = uploadId;
      if (loading) dataAttrs["data-loading"] = "true";
      if (error) dataAttrs["data-error"] = error;
      return [
        "video",
        mergeAttributes(this.options.HTMLAttributes || {}, rest, dataAttrs, {
          controls: "",
        }),
      ];
    },
  });

  function getVideoDimensions(src) {
    return new Promise((resolve, reject) => {
      const video = document.createElement("video");
      video.preload = "metadata";
      video.onloadedmetadata = () => {
        resolve({ width: video.videoWidth, height: video.videoHeight });
        video.src = "";
      };
      video.onerror = reject;
      video.src = src;
    });
  }

  function uploadAndInsertVideo(file, view, pos = null) {
    const uploadId = `upload-${Date.now()}-${Math.random()
      .toString(36)
      .substring(2, 9)}`;

    const objectUrl = URL.createObjectURL(file);

    getVideoDimensions(objectUrl)
      .catch(() => ({ width: null, height: null }))
      .then((dimensions) => {
        URL.revokeObjectURL(objectUrl);
        uploadMap.set(uploadId, { file });

        const attrs = {
          src: objectUrl,
          uploadId: uploadId,
          loading: true,
          width: dimensions.width,
          height: dimensions.height,
        };

        const node = view.state.schema.nodes.video.create(attrs);
        const tr = view.state.tr;

        if (pos != null) {
          tr.insert(pos, node);
        } else {
          tr.insert(tr.selection.from, node);
        }
        view.dispatch(tr);

        const postName = getPostName();
        return uploadFile(file);
      })
      .then((result) => {
        view.state.doc.descendants((node, nodePos) => {
          if (node.type.name === "video" && node.attrs.uploadId === uploadId) {
            const tr = view.state.tr.setNodeMarkup(nodePos, undefined, {
              ...node.attrs,
              src: result.file_url,
              loading: false,
            });
            view.dispatch(tr);
            uploadMap.delete(uploadId);
            return false;
          }
        });
      })
      .catch((error) => {
        view.state.doc.descendants((node, nodePos) => {
          if (node.type.name === "video" && node.attrs.uploadId === uploadId) {
            const tr = view.state.tr.setNodeMarkup(nodePos, undefined, {
              ...node.attrs,
              loading: false,
              error: error.message || "Failed to upload video",
            });
            view.dispatch(tr);
            return false;
          }
        });
      });
  }

  // ===================== End File Upload Helpers =====================

  const editorElement = document.getElementById("editor");
  if (!editorElement) return;

  // Inject CSS for the placeholder
  if (!document.getElementById("tiptap-placeholder-css")) {
    const style = document.createElement("style");
    style.id = "tiptap-placeholder-css";
    style.innerHTML = `
      .tiptap p.is-editor-empty:first-child::before {
        color: #adb5bd;
        content: attr(data-placeholder);
        float: left;
        height: 0;
        pointer-events: none;
      }
    `;
    document.head.appendChild(style);
  }

  // Insert Toolbar HTML before the editor
