        z-index: 100;
        background-color: #ffffff;
        width: 100%;
        box-sizing: border-box;
      }
      #editor-toolbar .tb-group {
        display: inline-flex;
        align-items: center;
        gap: 6px;
        flex-wrap: wrap;
      }
      #editor-toolbar .tb-btn {
        display: flex;
        align-items: center;
        justify-content: center;
        border-radius: 4px;
        padding: 4px;
        color: #334155;
        transition: background-color 150ms ease, color 150ms ease;
        background-color: transparent;
        border: none;
        cursor: pointer;
        font-size: 13px;
      }
      #editor-toolbar .tb-btn:hover {
        background-color: #f1f5f9;
      }
      #editor-toolbar .tb-btn.is-active {
        background-color: #e2e8f0;
      }
      #editor-toolbar .tb-icon {
        height: 16px;
        width: 16px;
      }
      #editor-toolbar .tb-text {
        display: inline-block;
        height: 16px;
        min-width: 16px;
        font-size: 14px;
        line-height: 16px;
        font-weight: 600;
        text-align: center;
        font-family: inherit;
      }
      #editor-toolbar .tb-separator {
        height: 16px;
        width: 1px;
        background-color: #e2e8f0;
        margin: 0 2px;
      }
      #editor-toolbar .tb-dropdown-container {
        position: relative;
        display: inline-block;
      }
      #editor-toolbar .tb-dropdown-menu {
        position: absolute;
        top: 100%;
        left: 0;
        z-index: 10;
        background-color: #ffffff;
        border: 1px solid rgba(0, 0, 0, 0.05);
        border-radius: 12px;
        box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.25);
        padding: 6px;
        margin-top: 8px;
        display: none;
        flex-direction: column;
        gap: 2px;
      }
      #editor-toolbar .tb-dropdown-menu:focus {
        outline: none;
      }
      #editor-toolbar .tb-dropdown-menu.is-open {
        display: flex;
      }
      #editor img[data-loading="true"],
      #editor video[data-loading="true"] {
        opacity: 0.5;
        animation: upload-pulse 2s cubic-bezier(0.4, 0, 0.6, 1) infinite;
      }
      @keyframes upload-pulse {
        0%, 100% { opacity: 0.5; }
        50% { opacity: 0.85; }
      }
      #editor video {
        max-width: 100%;
        border-radius: 4px;
      }
      #editor video[data-error] {
        border: 2px solid #ef4444;
        cursor: pointer;
      }

    </style>
    <div id="editor-toolbar">
      <div class="tb-group">
        <button class="tb-btn" data-action="p" title="Paragraph">
          <svg class="tb-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="4 7 4 4 20 4 20 7"></polyline><line x1="9" y1="20" x2="15" y2="20"></line><line x1="12" y1="4" x2="12" y2="20"></line></svg>
        </button>
        <div class="tb-dropdown-container" id="heading-dropdown">
          <button class="tb-btn" id="heading-btn" title="Heading">
            <svg class="tb-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M7 12h10"></path><path d="M7 5v14"></path><path d="M17 5v14"></path></svg>
          </button>
          <div class="tb-dropdown-menu" id="heading-menu">
            <button class="tb-btn" style="width: 100%; min-width: max-content; justify-content: flex-start; " data-action="h1">H1</button>
            <button class="tb-btn" style="width: 100%; min-width: max-content; justify-content: flex-start; " data-action="h2">H2</button>
            <button class="tb-btn" style="width: 100%; min-width: max-content; justify-content: flex-start; " data-action="h3">H3</button>
            <button class="tb-btn" style="width: 100%; min-width: max-content; justify-content: flex-start; " data-action="h4">H4</button>
            <button class="tb-btn" style="width: 100%; min-width: max-content; justify-content: flex-start; " data-action="h5">H5</button>
            <button class="tb-btn" style="width: 100%; min-width: max-content; justify-content: flex-start; " data-action="h6">H6</button>
          </div>
        </div>


        <div class="tb-separator"></div>

        <button class="tb-btn" data-action="bold" title="Bold">
          <svg class="tb-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M6 4h8a4 4 0 0 1 4 4 4 4 0 0 1-4 4H6z"></path><path d="M6 12h9a4 4 0 0 1 4 4 4 4 0 0 1-4 4H6z"></path></svg>
        </button>
        <button class="tb-btn" data-action="italic" title="Italic">
          <svg class="tb-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><line x1="19" y1="4" x2="10" y2="4"></line><line x1="14" y1="20" x2="5" y2="20"></line><line x1="15" y1="4" x2="9" y2="20"></line></svg>
        </button>
        <button class="tb-btn" data-action="strike" title="Strikethrough">
          <svg class="tb-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><line x1="5" y1="12" x2="19" y2="12"></line><path d="M16 6C16 6 14.745 4 12 4 9.255 4 8 6 8 6"></path><path d="M8 18c0 0 1.255 2 4 2 2.745 0 4-2 4-2"></path></svg>
        </button>
        <button class="tb-btn" data-action="link" title="Link">
          <svg class="tb-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M10 13a5 5 0 0 0 7.54.54l3-3a5 5 0 0 0-7.07-7.07l-1.72 1.71"></path><path d="M14 11a5 5 0 0 0-7.54-.54l-3 3a5 5 0 0 0 7.07 7.07l1.71-1.71"></path></svg>
        </button>
        <button class="tb-btn" data-action="color" title="Font Color">
          <svg class="tb-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 2v20"></path><path d="M17 5H9.5a3.5 3.5 0 0 0 0 7h5a3.5 3.5 0 0 1 0 7H6"></path></svg>
        </button>

        <div class="tb-separator"></div>

        <button class="tb-btn" data-action="bulletList" title="Bullet List">
          <svg class="tb-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><line x1="8" y1="6" x2="21" y2="6"></line><line x1="8" y1="12" x2="21" y2="12"></line><line x1="8" y1="18" x2="21" y2="18"></line><line x1="3" y1="6" x2="3.01" y2="6"></line><line x1="3" y1="12" x2="3.01" y2="12"></line><line x1="3" y1="18" x2="3.01" y2="18"></line></svg>
