      handleDOMEvents: {
        drop(view, event) {
          const hasFiles = event.dataTransfer?.files?.length;
          if (!hasFiles) return false;

          const images = Array.from(event.dataTransfer.files).filter((file) =>
            file.type.startsWith("image/"),
          );
          const videos = Array.from(event.dataTransfer.files).filter((file) =>
            file.type.startsWith("video/"),
          );
          if (images.length === 0 && videos.length === 0) return false;

          event.preventDefault();

          const coordinates = view.posAtCoords({
            left: event.clientX,
            top: event.clientY,
          });

          let pos = coordinates ? coordinates.pos : view.state.selection.from;
          images.forEach((file) => uploadAndInsertImage(file, view, pos));
          videos.forEach((file) => uploadAndInsertVideo(file, view, pos));
          return true;
        },
        paste(view, event) {
          const items = event.clipboardData?.items;
          if (!items) return false;

          const images = [];
          const videos = [];
          for (let i = 0; i < items.length; i++) {
            const item = items[i];
            if (item.kind === "file") {
              if (item.type.startsWith("image/")) {
                const file = item.getAsFile();
                if (file) images.push(file);
              } else if (item.type.startsWith("video/")) {
                const file = item.getAsFile();
                if (file) videos.push(file);
              }
            }
          }

          if (images.length === 0 && videos.length === 0) return false;

          event.preventDefault();
          images.forEach((file) => uploadAndInsertImage(file, view));
          videos.forEach((file) => uploadAndInsertVideo(file, view));
          return true;
        },
